#!/bin/bash
# start-tomcat.sh — generated by happy-spring-tomcat extension
set -o pipefail
echo "==================================================="
echo "Starting Tomcat in DEBUG mode (Port 8000)..."
echo "HTTP Port: 8080"
printf '%s
' 'Context Path: '
echo "==================================================="
echo "Cleaning up previous Tomcat instances..."
hst_stop_owned_port() {
    local port="$1" pid command foreign=0
    for pid in $(lsof -tiTCP:"$port" -sTCP:LISTEN 2>/dev/null); do
        command=$(ps -p "$pid" -o args= 2>/dev/null || true)
        case "$command" in
            *"-Dcatalina.base=$CATALINA_BASE"*) kill -9 "$pid" ;;
            *) echo "Port $port belongs to another process (PID $pid); it was not stopped." >&2; foreign=1 ;;
        esac
    done
    return "$foreign"
}

export CATALINA_BASE='/home/falcons/.config/Code/User/workspaceStorage/75525f1fe6141f7fa1b57db5d68c0066/skay138.happy-spring-tomcat/tomcat-base'
hst_stop_owned_port 8000 || exit 1
hst_stop_owned_port 8080 || exit 1
sleep 1

export JAVA_OPTS='-Dfile.encoding=UTF-8 -Dsun.stdout.encoding=UTF-8 -Dsun.stderr.encoding=UTF-8'
export CATALINA_HOME='/home/falcons/Desktop/Maktab Sharif/java-server/apache-tomcat-11.0.25'
export JPDA_ADDRESS="127.0.0.1:8000"
export JPDA_TRANSPORT="dt_socket"

echo "Tomcat is launching (HTTP Port 8080)..."
"$CATALINA_HOME/bin/catalina.sh" jpda run 2>&1 | awk -f "$(dirname "$0")/colorize-logs.awk"
hst_catalina_exit=$?
if [ -f "$(dirname "$0")/restart-requested" ]; then
    rm -f "$(dirname "$0")/restart-requested"
    echo "Tomcat start was interrupted by Restart."
    exit 0
fi
echo "Tomcat process exited."
exit "$hst_catalina_exit"
